13	// StripFences removes ```...``` code blocks so illustrative links are ignored.
14	var fenceRegex = regexp.MustCompile("(?s)```.*?```")
15	
16	func StripFences(text string) string {
17		return fenceRegex.ReplaceAllString(text, "")
18	}
