123	// LoadBundle loads all concepts, indexes, and logs from a bundle directory and builds the relationship graph.
124	// A bundle root that is a symlink must resolve to a location inside the directory containing the link.
125	func LoadBundle(root string) (*Bundle, error) {
126		return loadBundle(root, false)
