129	// loadTrustedBundle loads a bundle whose root the user configured explicitly (user and system scope).
130	// Such a root may be a symlink to any location; symlinks inside the bundle remain confined to it.
131	func loadTrustedBundle(root string) (*Bundle, error) {
132		return loadBundle(root, true)
133	}
