135	// resolveBundleRoot returns the canonical directory to walk and the root path to report for the bundle at root.
136	func resolveBundleRoot(root string, trustedRoot bool) (walkRoot, bundlePath string, err error) {
137		realRoot, err := filepath.EvalSymlinks(root)
138		if err != nil {
139			return "", "", fmt.Errorf("bundle directory does not exist: %w", err)
140		}
141		realRoot, err = filepath.Abs(realRoot)
142		if err != nil {
143			return "", "", fmt.Errorf("failed to get absolute path of bundle root: %w", err)
144		}
145	
146		if !trustedRoot {
147			if err := ensureRootWithinParent(root, realRoot); err != nil {
148				return "", "", err
149			}
150		}
151	
152		info, err := os.Stat(realRoot)
153		if err != nil {
154			return "", "", fmt.Errorf("bundle directory does not exist: %w", err)
155		}
156		if !info.IsDir() {
157			return "", "", fmt.Errorf("path is not a directory: %s", root)
158		}
159	
160		// If root itself does not contain index.md, but contains a knowledge/ subdirectory,
161		// resolve to the nested knowledge/ bundle directory (e.g. project root with DMAA layout).
162		if _, err := os.Stat(filepath.Join(realRoot, "index.md")); !os.IsNotExist(err) {
163			return realRoot, root, nil
164		}
165		if kInfo, kErr := os.Stat(filepath.Join(realRoot, "knowledge")); kErr != nil || !kInfo.IsDir() {
166			return realRoot, root, nil
167		}
168		knowledgeRoot, err := ensureWithinRoot(realRoot, "knowledge")
169		if err != nil {
170			return "", "", err
171		}
172		return knowledgeRoot, filepath.Join(root, "knowledge"), nil
173	}
