187	// parseRootIndexFrontmatter extracts okf_version and optional scopes configuration from root index.md.
188	// If 'scopes' is present, it must be a non-empty list containing only canonical scopes (project, vendor, user, system).
189	func parseRootIndexFrontmatter(fmText string) (string, []Scope, error) {
190		type fmBlock struct {
191			inline string
192			lines  []string
193		}
194		blocks := make(map[string]*fmBlock)
195		var curBlock *fmBlock
196	
197		for _, line := range strings.Split(fmText, "\n") {
198			line = strings.TrimRight(line, "\r")
199			trimmed := strings.TrimSpace(line)
200			if trimmed == "" || strings.HasPrefix(trimmed, "#") {
201				continue
202			}
203			if strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t") || (curBlock != nil && strings.HasPrefix(line, "-")) {
204				if curBlock != nil {
205					curBlock.lines = append(curBlock.lines, line)
206				}
207				continue
208			}
209			before, after, ok := cutYAMLPair(line)
210			if !ok {
211				continue
212			}
213			key := unquote(before)
214			val := strings.TrimSpace(after)
215			curBlock = &fmBlock{inline: val}
216			blocks[key] = curBlock
217		}
218	
219		var declaredVer string
220		if verBlock, ok := blocks["okf_version"]; ok {
221			declaredVer = unquote(verBlock.inline)
222		}
223	
224		scopesBlock, hasScopes := blocks["scopes"]
225		if !hasScopes {
226			return declaredVer, nil, nil
227		}
228	
229		rawItems, err := parseStrictScopesList(scopesBlock.inline, scopesBlock.lines)
230		if err != nil {
231			return "", nil, err
232		}
233		if len(rawItems) == 0 {
234			return "", nil, fmt.Errorf("invalid scopes in index.md: scopes list cannot be empty")
235		}
236	
237		var scopes []Scope
238		seen := make(map[Scope]bool)
239		for _, raw := range rawItems {
240			norm := Scope(strings.ToLower(strings.TrimSpace(raw)))
241			switch norm {
242			case ScopeProject, ScopeVendor, ScopeUser, ScopeSystem:
243				if !seen[norm] {
244					seen[norm] = true
245					scopes = append(scopes, norm)
246				}
247			default:
248				return "", nil, fmt.Errorf("invalid scope %q in index.md (allowed: project, vendor, user, system)", raw)
249			}
250		}
251		return declaredVer, scopes, nil
252	}
253	
254	func parseStrictScopesList(inline string, blockLines []string) ([]string, error) {
255		var out []string
256		s := strings.TrimSpace(inline)
257		if s != "" {
258			if strings.HasPrefix(s, "[") {
259				if !strings.HasSuffix(s, "]") {
260					return nil, fmt.Errorf("invalid scopes in index.md: malformed flow list %q", inline)
261				}
262				inner := strings.TrimSpace(s[1 : len(s)-1])
263				if inner == "" {
264					return nil, nil
265				}
266				for _, item := range splitFlowItems(inner) {
267					it := unquote(item)
268					if it == "" {
269						return nil, fmt.Errorf("invalid scopes in index.md: empty item in scopes list")
270					}
271					out = append(out, it)
272				}
273				return out, nil
274			}
275			return []string{unquote(s)}, nil
276		}
277	
278		for _, line := range blockLines {
279			trimmed := strings.TrimSpace(line)
280			if trimmed == "" || strings.HasPrefix(trimmed, "#") {
281				continue
282			}
283			after, ok := strings.CutPrefix(trimmed, "-")
284			if !ok {
285				return nil, fmt.Errorf("invalid scopes in index.md: unexpected block line %q", trimmed)
286			}
287			val := unquote(strings.TrimSpace(after))
288			if val == "" {
289				return nil, fmt.Errorf("invalid scopes in index.md: empty item in scopes list")
290			}
291			out = append(out, val)
292		}
293		return out, nil
294	}
