447	func (b *Bundle) buildGraph() {
448		linkedNodes := make(map[string]bool)
449	
450		for id := range b.Concepts {
451			b.Graph[id] = make([]string, 0)
452			if _, ok := b.InboundGraph[id]; !ok {
453				b.InboundGraph[id] = make([]string, 0)
454			}
455		}
456	
457		for id, concept := range b.Concepts {
458			body := StripFences(concept.Body)
459			matches := linkRegex.FindAllStringSubmatch(body, -1)
460	
461			for _, match := range matches {
462				href := match[1]
463				if IsExternalLink(href) {
464					linkedNodes[id] = true // Outbound external reference prevents false orphan flag
465					continue               // External URL or Qualified Scope URI: hermetic CI ignores remote target
466				}
467	
468				targetID := b.ResolveLink(concept.Path, href)
469				targetRel := targetID + ".md"
470				targetBase := path.Base(targetRel)
471	
472				if strings.EqualFold(targetBase, "index.md") || strings.EqualFold(targetRel, "log.md") || strings.EqualFold(targetRel, "AGENTS.md") {
473					b.BrokenLinks = append(b.BrokenLinks, BrokenLink{
474						SourceConcept: concept.Path,
475						TargetHref:    href,
476						Reason:        "reserved index.md/log.md/AGENTS.md is navigation, not a concept",
477					})
478					continue
479				}
480	
481				if _, exists := b.Concepts[targetID]; exists {
482					if targetID != id {
483						b.Graph[id] = append(b.Graph[id], targetID)
484						b.InboundGraph[targetID] = append(b.InboundGraph[targetID], id)
485						linkedNodes[id] = true
486						linkedNodes[targetID] = true
487					}
488				} else {
489					b.BrokenLinks = append(b.BrokenLinks, BrokenLink{
490						SourceConcept: concept.Path,
491						TargetHref:    href,
492						Reason:        "target concept does not exist",
493					})
494				}
495			}
496		}
497	
498		// Also check for broken links inside directory indexes (index.md)
499		for idxPath, idxContent := range b.Indexes {
500			body := StripFences(idxContent)
501			matches := linkRegex.FindAllStringSubmatch(body, -1)
502	
503			for _, match := range matches {
504				href := match[1]
505				if IsExternalLink(href) {
506					continue // External URL or Qualified Scope URI: hermetic CI ignores remote target
507				}
508	
509				targetID := b.ResolveLink(idxPath, href)
510				targetRel := targetID + ".md"
511				targetBase := path.Base(targetRel)
512	
513				if strings.EqualFold(targetBase, "index.md") || strings.EqualFold(targetRel, "log.md") || strings.EqualFold(targetRel, "AGENTS.md") {
514					continue // Reserved files in indexes are standard navigation
515				}
516	
517				if _, exists := b.Concepts[targetID]; !exists {
518					b.BrokenLinks = append(b.BrokenLinks, BrokenLink{
519						SourceConcept: idxPath,
520						TargetHref:    href,
521						Reason:        "target concept does not exist",
522					})
523				}
524			}
525		}
526	
527		// Compute orphans (degree 0 in concept graph when bundle has > 1 concept)
528		if len(b.Concepts) > 1 {
529			for id := range b.Concepts {
530				if !linkedNodes[id] {
531					b.Orphans = append(b.Orphans, id)
532				}
533			}
534		}
535	}
