13	const (
14		// bundleWriteLockFile is the dot-prefixed lock file created inside a bundle root
15		// to serialize concurrent local Read-Modify-Write transactions across processes.
16		// Dot-prefixed files are ignored by LoadBundle, Validate, and vault sync scanners.
17		bundleWriteLockFile = ".okf-write.lock"
18	
19		defaultLockTimeout  = 10 * time.Second
20		defaultStaleLockAge = 30 * time.Second
21	)
22	
23	// ErrConcurrentModification is returned by SaveConcept when an existing concept
24	// loaded via LoadBundle was modified on disk by another writer before SaveConcept
25	// acquired the bundle lock (Optimistic Concurrency Check / CAS failure).
26	var ErrConcurrentModification = errors.New("concurrent modification detected")
27	
28	// ErrConceptNotFound is returned by UpdateConcept when the target concept ID
29	// does not exist in the loaded bundle.
30	var ErrConceptNotFound = errors.New("concept not found")
