32	func hashConceptContent(content string) string {
33		sum := sha256.Sum256([]byte(content))
34		return hex.EncodeToString(sum[:])
35	}
36	
37	// WithBundleLock acquires an exclusive cross-process write lock for the bundle
38	// at bundleDir, executes fn, and releases the lock.
39	func WithBundleLock(bundleDir string, fn func() error) error {
40		return withBundleLockConfig(bundleDir, defaultLockTimeout, defaultStaleLockAge, fn)
41	}
42	
43	func withBundleLockConfig(bundleDir string, timeout, staleAge time.Duration, fn func() error) error {
44		if err := os.MkdirAll(bundleDir, 0o755); err != nil {
45			return fmt.Errorf("failed to create bundle directory for lock: %w", err)
46		}
47	
48		lockPath, err := ensureWithinRoot(bundleDir, bundleWriteLockFile)
49		if err != nil {
50			return fmt.Errorf("unsafe bundle lock path: %w", err)
51		}
52	
53		releaseFileLock, err := acquireFileLock(lockPath, timeout, staleAge)
54		if err != nil {
55			return err
56		}
57		defer releaseFileLock()
58	
59		return fn()
60	}
61	
62	func acquireFileLock(lockPath string, timeout, staleAge time.Duration) (func(), error) {
63		deadline := time.Now().Add(timeout)
64		backoff := 500 * time.Microsecond
65		const maxBackoff = 15 * time.Millisecond
66	
67		for {
68			// #nosec G304 -- lockPath is confined to bundle root via ensureWithinRoot
69			f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
70			if err == nil {
71				meta := fmt.Sprintf("pid=%d\nacquired_at=%s\n", os.Getpid(), time.Now().UTC().Format(time.RFC3339Nano))
72				_, _ = f.WriteString(meta)
73				_ = f.Close()
74	
75				return func() {
76					_ = os.Remove(lockPath)
77				}, nil
78			}
79	
80			if !errors.Is(err, os.ErrExist) {
81				return nil, fmt.Errorf("failed to acquire bundle write lock %q: %w", lockPath, err)
82			}
83	
84			if staleAge > 0 && isLockStale(lockPath, staleAge) {
85				_ = os.Remove(lockPath)
86				continue
87			}
88	
89			if time.Now().After(deadline) {
90				return nil, fmt.Errorf("timed out waiting for bundle write lock %q after %s", lockPath, timeout)
91			}
92	
93			time.Sleep(backoff)
94			if backoff < maxBackoff {
95				backoff *= 2
96				if backoff > maxBackoff {
97					backoff = maxBackoff
98				}
99			}
100		}
101	}
102	
103	func isLockStale(lockPath string, staleAge time.Duration) bool {
104		// #nosec G304 -- lockPath is confined to bundle root via ensureWithinRoot
105		if data, err := os.ReadFile(lockPath); err == nil {
106			for _, line := range strings.Split(string(data), "\n") {
107				if after, ok := strings.CutPrefix(strings.TrimSpace(line), "acquired_at="); ok {
108					if ts, parseErr := time.Parse(time.RFC3339Nano, strings.TrimSpace(after)); parseErr == nil {
109						return time.Since(ts) > staleAge
110					}
111				}
112			}
113		}
114		info, err := os.Stat(lockPath)
115		if err != nil {
116			return false
117		}
118		return time.Since(info.ModTime()) > staleAge
119	}
